ssion":"guided-tour affiliate","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination"},"commission_lane":["affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Site Museum + Pakal reconstructed tomb exhibit","tier":"essential","source":"https://mayaruins.com/palenque/a1_223.html","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"bundled admission (non-commissionable)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination"},"commission_lane":["bundle"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Bonampak murals (~792 AD)","tier":"comfort","source":"https://www.viator.com/tours/Palenque/Tour-Bonampak-and-Yaxchilan/d23479-30922P9","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"best-preserved Classic Maya murals on Earth, full-color three-room cycle","si":"culture","blurb":"best-preserved Classic Maya murals on Earth, full-color three-room cycle","when":"Nov–Apr","commission":"full-day DMC tour","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Yaxchilán by Usumacinta riverboat","tier":"premier","source":"https://www.viator.com/tours/Palenque/Tour-Bonampak-and-Yaxchilan/d23479-30922P9","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Usumacinta motorboat into the Lacandón, ruins the road cannot reach","si":"culture","blurb":"Usumacinta motorboat into the Lacandón, ruins the road cannot reach","when":"Nov–Apr","commission":"licensed river-tour DMC (border-v