insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('paracas-nazca-peru', '10S', 'Paracas, Nazca & the South Coast', 'Peru', '*If it''s a desert oasis, a "poor man''s Galápagos,"', 'live', 'verified', 'desertDunes', 'Lima, South Coast & Amazon', '{"expedition","culture","culinary"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":["The South Coast is a desert-and-ocean circuit ~3–4 hr south of Lima on the Panamericana Sur — no altitude, no cloud-forest; the risks are activity/operator, not crime.","Ballestas Islands (''poor man''s Galápagos'') — sea lions, Humboldt penguins, boobies, 150+ bird species — visitable only by ~2-hr guided boat from El Chaco pier.","Nazca Lines are best seen on a ~30–35 min light-aircraft overflight from María Reiche Neuman aerodrome (NZC) — choose a reputable operator (accident history; 2022 fatal crash) and expect banking-turn motion sickness.","Huacachina is a real palm-ringed desert oasis outside Ica; the marquee is the sunset dune-buggy + sandboard circuit — ride only permitted buggies (four-point belts + roll cages).","Paracas National Reserve (~S/11 entry) has Playa Roja (Red Beach) and La Catedral; swimming is prohibited at Playa Roja (open swell, strong currents, no lifeguards)."],"safety":{"emergency":"105","emergency_ambulance":"117","emergency_fire":"116","tourist_line":"iPerú / Policía de Turismo","hospital":"Ica & Pisco clinics for routine/stabilization; serious cases evac to Lima (Clínica Anglo Americana / Ricardo Palma); desert stretches remote","air_access_verified":true,"air_access_note":"Fly Lima (LIM); road ~3–4 hr south on the Panamericana Sur to Paracas/Ica; Nazca overflights depart María Reiche Neuman aerodrome (NZC)","activity_flags":{"nazca_overflight":"reputable/authorized operator only (accident history; 2022 fatal crash); small-plane turbulence + motion sickness; weather-suspension risk (wind/dust/garua)","huacachina_dune_buggy":"rollover risk; permitted operators only (four-point belts, roll cages, headrests, certified welds, <=15-yr vehicles); avoid informal ''tubular'' buggies","ballestas_boat":"open-ocean swell; life vests provided and worn","pacific_coast":"riptides, strong currents, no lifeguards; Playa Roja swimming prohibited; railing-less cliffs at La Catedral","wind_sport":"May–Sep kitesurf — school + PFD, offshore-wind hazard"},"sun":"high desert UV — sunscreen, hats, hydration","water":"bottled/purified only","malaria":"none on the arid South Coast (malaria risk is the low-elevation Amazon)","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/peru","read":"2026-09-01T16:20:02Z","page_updated":"2026-06-22T23:35:12+01:00","source_country":"peru","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"fcdo_zones":[{"name":"The VRAEM (Apurimac, Ene and Mantaro valley)","lvl":4},{"name":"The Colombia-border area of Loreto","lvl":4}]},"timing":{"peak":"December–April (Peruvian summer, hot/sunny; beach + desert; Paracas year-round as Lima escape)","event_peak":"Ica Vendimia grape-harvest festival — first weeks of March","inflection_curve_start":"summer: late Oct–early Nov; Vendimia: mid-to-late January","fire_date":"2026-10-20 (summer peak) / 2026-01-15 (Vendimia) — each = curve-start − 1–2 weeks","wind_sport_window":"May–September (winter; stronger Paracas winds; kitesurf; clearer Nazca skies but garua/gust flight-suspension risk)","shoulder":"April–May & October–November (best value)","booking_lead":"core circuit days–weeks; Huacachina sunset/weekend buggy 2–3 days; Vendimia + Dec–Apr Paracas resorts weeks–months","event_peaks":["Ica Vendimia (grape-harvest festival), March"],"off_season_specials":"winter wind-sport + shoulder value stays + year-round Lima day-trip/overnight bundles"},"jewels":[{"name":"Ballestas Islands (''poor man''s Galápagos'')","status":"live","hook":"Sea lions, Humboldt penguins, boobies & 150+ bird species under guano cliffs — 20 min off the pier","bookable_category":"guided_boat_tour","tier":"essential","source":"https://www.alongdustyroads.com/posts/islas-ballestas-tour-paracas","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Sea lions, Humboldt penguins, boobies & 150+ bird species under guano cliffs — 20 min off the pier","when":"December–April","commission":"boat operator via OutsideAgents/affiliate (embarkation fee non-commissionable)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Nazca Lines overflight + María Reiche viewpoint","status":"live","hook":"Bank over 2,000-year-old geoglyphs only the sky can read — hummingbird, monkey, spider, condor","bookable_category":"licensed_overflight","tier":"premier","source":"https://howtoperu.com/answers/nazca-lines-tower-vs-plane-costs-safety-cancellations/","timing":"year-round","timing_type":"ALWAYS-ON","si":"expedition","blurb":"Bank over 2,000-year-old geoglyphs only the sky can read — hummingbird, monkey, spider, condor","when":"year-round","commission":"authorized/reputable overflight operator via OutsideAgents (airport tax + site ticket non-commissionable)","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Huacachina oasis — dune-buggy + sandboard sunset","status":"live","hook":"Roller-coaster the dunes, then slide back down into the sunset from a real desert oasis","bookable_category":"dune_buggy_sandboard","tier":"essential","source":"https://bushop.com/peru/guides/huacachina-dune-buggy-sandboarding-prices-safety-and-best-time-of-day/","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Roller-coaster the dunes, then slide back down into the sunset from a real desert oasis","when":"December–April","commission":"permitted buggy operator via OutsideAgents/affiliate","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Paracas National Reserve — Playa Roja & La Catedral","status":"live","hook":"A crimson beach the color of Mars against yellow cliffs and a teal Pacific — look, don''t swim","bookable_category":"reserve_day_tour","tier":"essential","source":"https://www.paracasperu.com/guides/paracas-national-reserve-wildlife-hiking-park-entrance-guide/","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"A crimson beach the color of Mars against yellow cliffs and a teal Pacific — look, don''t swim","when":"December–April","commission":"reserve day-tour via OutsideAgents/affiliate (S/11 entry non-commissionable)","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Chauchilla Cemetery","status":"future","hook":"Naturally mummified Nazca-culture bodies in their original open desert tombs, textiles intact","bookable_category":"ground_tour_addon","tier":"comfort","source":"https://en.wikipedia.org/wiki/Chauchilla_Cemetery","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Naturally mummified Nazca-culture bodies in their original open desert tombs, textiles intact","when":"year-round","commission":"Nazca DMC/tour operator via OutsideAgents","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Tambo Colorado (Pisco valley)","status":"future","hook":"One of the best-preserved coastal Inca sites — adobe walls still red, the Spanish never wrecked it","bookable_category":"guided_excursion","tier":"comfort","source":"https://en.wikipedia.org/wiki/Tambo_Colorado","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"One of the best-preserved coastal Inca sites — adobe walls still red, the Spanish never wrecked it","when":"December–April","commission":"guided excursion from Paracas/Pisco via OutsideAgents","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination"},"commission_lane":["guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Paracas Candelabra geoglyph","status":"future","hook":"A 170 m desert trident visible 19 km out to sea — seen at the start of the Ballestas boat tour","bookable_category":"included_in_boat_tour","tier":"essential","source":"https://en.wikipedia.org/wiki/Paracas_Candelabra","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"A 170 m desert trident visible 19 km out to sea — seen at the start of the Ballestas boat tour","when":"December–April","commission":"included in Ballestas boat tour (affiliate)","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","expedition":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Ica pisco bodegas + Vendimia","status":"future","hook":"Stand where Peruvian pisco was born — Tacama, El Catador, Queirolo — and tread the grapes each March","bookable_category":"wine_pisco_tour","tier":"comfort","source":"https://quechuasperuviajes.com/festival-de-la-vendimia-de-ica","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Stand where Peruvian pisco was born — Tacama, El Catador, Queirolo — and tread the grapes each March","when":"December–April","commission":"Ica DMC/wine-tour operator via OutsideAgents","wells":["eat"],"wells_basis":"full pass 2026-10-05, additive — food SI (David 2026-10-05: every traveler has to eat)","si_all":["culinary"],"shelf_fit":{"culinary":"primary","culture":"destination","expedition":"destination"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"2026-10-05: Fora removed - excluded by David 2026-09-05; the remaining route kept","commission_was":"Ica DMC/wine-tour operator via OutsideAgents/Fora"}],"faq":[{"q":"Can you swim at the Paracas beaches?","a":"Not at the reserve beaches. Playa Roja and the reserve coast have open swell, strong currents and no lifeguards — swimming is prohibited at Playa Roja, and the cliffs at La Catedral are crumbly and railing-less. Safe bay swimming is at the resort waterfronts, not inside the reserve (~S/11 entry).","source":"paracasperu.com, 2026-07-07","si_tag":"tropical","accessed":"2026-07-07"},{"q":"How old are the Nazca Lines, and what will I see?","a":"They date to the Nazca culture ~300–600 AD. From a ~30–35 min overflight you''ll pick out the hummingbird, monkey, spider and condor cut into the desert at a scale invisible from the ground; a roadside mirador shows 2–3 figures for those who''d rather not fly.","source":"howtoperu.com, 2026-07-07","si_tag":"culture","accessed":"2026-07-07"},{"q":"What''s the Ica Vendimia and pisco scene?","a":"Ica is the cradle of Peruvian pisco and wine. Historic bodegas — Tacama, Vista Alegre, El Catador, Ocucaje, Queirolo/Intipalka — run tastings year-round, peaking at the March Vendimia grape-harvest festival with 40+ activities, grape-treading and tastings across the city.","source":"quechuasperuviajes.com, 2026-07-07","si_tag":"culinary","accessed":"2026-07-07"},{"q":"What''s the real risk to plan for?","a":"Activity safety and operator choice, not crime. The load-bearing calls are the Nazca light-aircraft overflight (authorized operators only; 2022 fatal crash), the Huacachina dune-buggy (rollover risk), Ballestas boat life-vests and Pacific riptides. High winds/dust and winter garúa can also suspend flights.","source":"howtoperu.com, 2026-07-07","si_tag":"safety","accessed":"2026-07-07"},{"q":"Is the Huacachina dune buggy dangerous?","a":"It carries real rollover risk on the steep dunes, so operator choice matters. Peru''s minimum standard requires four-point seatbelts, roll cages, headrests, certified welds and a 15-year max vehicle age; the transport ministry has warned against informal \"tubular\" buggies. Ride only permitted operators and check your belts.","source":"bushop.com, 2026-07-07","si_tag":"safety","accessed":"2026-07-07"}],"seo":{"jsonld_type":"TouristDestination","content_freshness":"2026-07-07","meta_title":"Paracas, Nazca & Peru''s South Coast — Ballestas, Nazca Lines, Huacachina Dunes & When to Go (2026)","search_language":"es-PE","local_keywords":["Islas Ballestas tour","Líneas de Nazca sobrevuelo","Huacachina oasis","Paracas","Reserva Nacional de Paracas Playa Roja","tubular Huacachina sandboard","bodegas de pisco Ica","Festival de la Vendimia Ica","Tambo Colorado Pisco","cementerio de Chauchilla","Candelabro de Paracas"],"hreflang":["en","es-PE"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-07","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/peru","read":"2026-08-20T14:53:51Z","source_updated":"2026-06-22T23:35:12+01:00"}]}},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"future"},{"si":"culinary","status":"future"}],"ultra":[{"name":"Hotel Paracas, a Luxury Collection Resort (Marriott)","why_ultra":"Bay''s marquee 5-star — private dock, spa, standout dining, secluded rooms facing the reserve","earning":"Marriott/Luxury Collection commission via Fora/Virtuoso (or STARS/Luminous)","virtuoso_value_add":"STARS/Virtuoso perks: breakfast, property credit, upgrades; private boat/reserve arrangements","mor":"Hotel/DMC direct or Fora","tier":"luxury"},{"name":"La Hacienda Bahia Paracas","why_ultra":"Bay-edge premier resort — gardens, pool, near-inclusive feel, world-class on-site museum","earning":"Hotel commission via Fora/OutsideAgents","virtuoso_value_add":"Amenity/credit perks + pre-arranged Ballestas/reserve","mor":"Hotel/DMC direct or Fora","tier":"premier"},{"name":"Hotel Vinas Queirolo (Ica)","why_ultra":"First/only hotel inside a working ~700-ha vineyard in Peru — pisco/wine tastings, three pools, vineyard views","earning":"Hotel commission via Fora/OutsideAgents","virtuoso_value_add":"Pre-loaded wine/pisco tastings + vineyard experiences; romantic-getaway framing","mor":"Hotel/DMC direct or Fora","tier":"premier–luxury"}],"source_verified":"2026-07-07","hero":{"query":"Paracas, Nazca & the South Coast, Peru"},"geo":{"lat":-13.86,"lng":-76.2517},"orbit":[{"id":"arequipa-colca-canyon-peru","jewels":12,"si":["expedition","romance","culture"]},{"id":"lake-titicaca-puno-peru","jewels":8,"si":["culture"]},{"id":"lima-peru","jewels":12,"si":["romance","expedition","culinary","culture"]},{"id":"tambopata-amazon-peru","jewels":10,"si":["expedition","wildlife","romance","river"]}],"orbit_country":["cusco-peru","machu-picchu-peru"]}'::jsonb, 81),
