d190"}],"seo":{"meta_title":"Pucón, Chile Travel Guide — Villarrica Volcano, Hot Springs & Lake District Adventure | TravelWell","search_language":"es-CL","local_keywords":["qué hacer en Pucón","volcán Villarrica ascenso","Termas Geométricas","Parque Nacional Huerquehue","rafting río Trancura","termas cerca de Pucón","Ojos del Caburgua","experiencia mapuche ruka","cuándo ir a Pucón","Pucón es seguro"],"hreflang":["en","es-CL"],"jsonld_type":"TouristDestination","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/chile","read":"2026-08-20T14:47:39Z","source_updated":"2026-08-18T23:18:12+01:00"}]},"content_freshness":"2026-07-07"},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Hotel Antumalal","tier":"ULTRA/icon","earning":"consortia-commissionable (Virtuoso/Fora potential) + direct","note":"1950 Bauhaus icon on Lake Villarrica; 16 rooms + 3 chalets + Lake House; Pollak family-owned"},{"name":"andBeyond Vira Vira","tier":"ULTRA","earning":"andBeyond/consortia-commissionable + all-in MoR potential","note":"55-acre organic hacienda on the Liucura River; 6 lodge suites + 12 villa suites; guided-adventure inclusive"},{"name":"AWA / Puerto Varas ultra corridor (cross-ref)","tier":"ULTRA (cross-ref)","earning":"consortia + multi-property MoR","note":"two-lake/two-volcano ultra string pairing Pucón with Puerto Varas/Llanquihue"}],"source_verified":null,"hero":{"query":"Pucón & the Araucanía Lakes, Chile, Chile"},"geo":{"lat":-39.282,"lng":