  ('puerto-vallarta-mexico', '10S', 'Puerto Vallarta', 'Mexico', 'Humpback season on Banderas Bay', 'live', 'verified', 'tropicalBeach', 'Jalisco (Puerto Vallarta & Guadalajara)', '{"romance","expedition","ocean"}', '{}', '{"comfort","luxury"}', null, null, '{"key_facts":["Banderas Bay hosts ~500–700 humpback whales each winter; season ~Dec 8–Mar 23 (Source: mismaloyaxtreme.com, Accessed 2026-07-04)","Hotel Mousai is the only AAA Five-Diamond resort in Puerto Vallarta (Source: travellemming.com, Accessed 2026-07-04)","Conchas Chinas is PV''s premier villa enclave, the ''Beverly Hills of Puerto Vallarta'' (Source: casabayvillas.com, Accessed 2026-07-04)","Los Arcos National Park holds the deepest water in Banderas Bay for certified divers (Source: vallarta-adventures.com, Accessed 2026-07-04)","Served by PVR (Lic. Gustavo Díaz Ordaz Intl) with direct US/Canada/UK flights (Source: en.wikipedia.org, Accessed 2026-07-04)"],"safety":{"emergency":"911","hospital":"Hospital San Javier Marina (Level III, trauma-capable); Hospital CMQ (three 24/7 bilingual locations)","air_access_verified":"PVR (Lic. Gustavo Díaz Ordaz Intl)","malaria":"none in resort zone; dengue seasonal (rainy Jul–Oct)","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"Nov–Apr (dry; overlaps humpback season Dec–Mar)","shoulder":"May–Jun, late Oct","green":"Jul–Oct (rainy/hurricane season)","booking_lead":"Dec–Mar villas 4–6+ months; shoulder 6–10 weeks","off_season_specials":"Jul–Oct value campaign: beaches + diving + villa-with-chef (no whales)","event_peaks":"US/Canada winter holidays (late Dec–early Jan); spring break (Mar)","fire_date":"Aug–Sep for whale/Romance (Dec–Mar arrivals); May–Jun for green-season value"},"jewels":[{"name":"Humpback panga at dawn, Banderas Bay","status":"live","hook":"~500–700 humpbacks breed within sight of shore Dec–Mar","bookable_category":"tour","tier":"comfort","source":"https://mismaloyaxtreme.com/en/whale-watching-puerto-vallarta-2025-2026-guide/ (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"~500–700 humpbacks breed within sight of shore Dec–Mar","when":"Nov–Apr","commission":"DMC/tour affiliate ~8–15%","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","ocean":"destination","romance":"destination"},"commission_pct_low":8,"commission_pct_high":15,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Los Arcos National Park dive","status":"future","hook":"Deepest water in the bay — tunnels, rays, turtles","bookable_category":"tour","tier":"comfort","source":"https://www.vallarta-adventures.com/en/tour/scuba-los-arcos (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Deepest water in the bay — tunnels, rays, turtles","when":"Nov–Apr","commission":"tour affiliate ~8–12%","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean"],"shelf_fit":{"expedition":"destination","ocean":"primary","romance":"destination"},"commission_pct_low":8,"commission_pct_high":12,"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Marietas Islands","status":"future","hook":"Pacific mantas + reef fish + Hidden Beach","bookable_category":"tour","tier":"comfort","source":"https://www.vallarta-adventures.com/en/tour/scuba-las-marietas-islands (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Pacific mantas + reef fish + Hidden Beach","when":"Nov–Apr","commission":"tour affiliate ~8–12%","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean"],"shelf_fit":{"expedition":"destination","ocean":"primary","romance":"destination"},"commission_pct_low":8,"commission_pct_high":12,"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Casa Kimberly","status":"live","hook":"The Taylor/Burton love-story hotel, heart-shaped-tub suite","bookable_category":"hotel","tier":"luxury","source":"https://travellemming.com/hotels-in-puerto-vallarta/ (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"The Taylor/Burton love-story hotel, heart-shaped-tub suite","when":"Nov–Apr","commission":"hotel/host commission ~10%","accessed":"2026-07-04","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["romance"],"shelf_fit":{"expedition":"destination","ocean":"destination","romance":"primary"},"commission_pct_low":10,"commission_pct_high":10,"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Conchas Chinas villa with private chef","status":"live","hook":"Hillside beachfront villa, chef/butler, minutes from Romantic Zone","bookable_category":"villa","tier":"luxury","source":"https://villaexperience.com/city/puerto-vallarta/ (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Hillside beachfront villa, chef/butler, minutes from Romantic Zone","when":"Nov–Apr","commission":"villa-agency commission via host (MoR ~10%)","accessed":"2026-07-04","wells":["stay","eat"],"wells_basis":"derived from name/blurb/hook","si_all":["romance"],"shelf_fit":{"expedition":"destination","ocean":"destination","romance":"primary"},"commission_pct_low":10,"commission_pct_high":10,"commission_lane":[],"commission_embedded":false,"commission_basis":"band"}],"faq":[{"q":"What''s the real risk to plan for?","a":"Staying in the tourist zone, not the interior. Fly into PVR (no need to transit the restricted interior), remain within PV / the Banderas Bay resort corridor, and don''t self-drive into the Jalisco interior. Health-wise, dengue is seasonal in the Jul–Oct rains — use repellent — and there is no malaria in the resort zone.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"When and how can I see the whales?","a":"On a licensed panga, roughly Dec 8–Mar 23, best in the morning. Around 500–700 humpbacks arrive in Banderas Bay each winter to breed and calve within sight of shore; whales are federally protected, so keep the regulated distance and do not swim with them. Morning departures mean calmer seas.","source":"mismaloyaxtreme.com, 2026-07-04","si_tag":"expedition","accessed":"2026-07-04"},{"q":"Is Puerto Vallarta good for a honeymoon, and where''s the top end?","a":"Yes — it''s a mature honeymoon and destination-wedding market. The in-city ultra rung is narrow but real: Hotel Mousai is PV''s only AAA Five-Diamond (145 suites + 4 penthouses), and the 9-room Casa Kimberly is the Taylor/Burton love-story hotel. Peak is Nov–Apr; hold marquee rooms and villas early.","source":"travellemming.com, 2026-07-04","si_tag":"romance","accessed":"2026-07-04"},{"q":"Can beginners dive Los Arcos?","a":"Los Arcos is a certified-diver site, not a beginner pool — it holds the deepest water in Banderas Bay, with tunnels, arches, rays and turtles. Dive within your certification, and observe the DAN no-fly interval of 18–24 hours before boarding a flight from PVR. Marietas Islands is the other certified-reef option.","source":"vallarta-adventures.com, 2026-07-04","si_tag":"ocean-adventures-—-future","accessed":"2026-07-04"},{"q":"Where are the best villas?","a":"Conchas Chinas and Amapas. PV''s \"Beverly Hills\" hillside enclave holds beachfront estates with private chef and butler just 5–10 minutes from the Romantic Zone; book Dec–Mar (the whale-and-holiday peak) 4–6+ months ahead. Route villas as agency/host merchant-of-record, never net-rate resale.","source":"casabayvillas.com / villaexperience.com, 2026-07-04","si_tag":"tropical","accessed":"2026-07-04"}],"seo":{"meta_title":"Puerto Vallarta Travel Guide 2026 — Whales, Villas & Banderas Bay | TravelWell.World","meta_description":"Plan Puerto Vallarta: humpback whale season (Dec–Mar), luxury villas in Conchas Chinas, Five-Diamond resorts, and diving Los Arcos — with the FCDO advisory explained and PV''s named carve-out.","long_tail":["Puerto Vallarta humpback whale season dates","Conchas Chinas villa rental with chef","diving Los Arcos Puerto Vallarta"],"search_language":"es-MX","local_keywords":["avistamiento de ballenas Puerto Vallarta","villas de lujo Conchas Chinas","Puerto Vallarta es seguro 2026","buceo Los Arcos Puerto Vallarta","hoteles todo incluido Puerto Vallarta"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]},"primary_keyword":["Puerto Vallarta travel","Puerto Vallarta whale watching","Puerto Vallarta luxury villas","is Puerto Vallarta safe 2026"]},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"expedition","status":"live"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Hotel Mousai","why_ultra":"Only AAA Five-Diamond resort in PV; hilltop suites + penthouses over Banderas Bay","earning":"on application / via host","virtuoso_value_add":"verify Virtuoso/preferred; if listed, breakfast + credit + upgrade","mor":"hotel"},{"name":"Garza Blanca Preserve Resort & Spa","why_ultra":"Private-beach sister to Mousai; shared facilities","earning":"on application / via host","virtuoso_value_add":"verify","mor":"hotel"},{"name":"Casa Kimberly","why_ultra":"9-room Taylor/Burton icon, bay-view Taylor suite","earning":"host/hotel commission on application","virtuoso_value_add":"verify","mor":"hotel"},{"name":"Conchas Chinas / Amapas luxury villas (e.g. Villa Amapas South)","why_ultra":"~7,000 sq ft beachfront estate, chef/butler","earning":"villa-agency commission via host, on application","virtuoso_value_add":"n/a (villa)","mor":"agency/host (never net-rate resale)"},{"name":"One&Only Mandarina [Nayarit — state-line flag]","why_ultra":"Ultra resort in neighboring Riviera Nayarit, inside PV safety carve-out","earning":"on application / via host-Virtuoso","virtuoso_value_add":"verify","mor":"hotel"}],"source_verified":"2026-07-04","hero":{"query":"Puerto Vallarta, Mexico"},"geo":{"lat":20.6534,"lng":-105.2253},"orbit":[{"id":"careyes-mexico","jewels":7,"si":["ultra","romance","ocean"]},{"id":"chapala-ajijic-mexico","jewels":6,"si":["wellness","culture","senior"]},{"id":"costalegre-mexico","jewels":7,"si":["tropical","romance","ultra","ocean"]},{"id":"guadalajara-mexico","jewels":8,"si":["culture","culinary","entertainment","sports"]},{"id":"mazamitla-mexico","jewels":6,"si":["expedition","family","adventure"]},{"id":"san-sebastian-del-oeste-mexico","jewels":6,"si":["culture","expedition","culinary"]},{"id":"tlaquepaque-mexico","jewels":4,"si":["culture","culinary"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","celestun-mexico","chichen-itza-mexico","coba-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","sayulita-mexico","sian-kaan-mexico","teotihuacan-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 89),
  ('puerto-viejo-costa-rica', '10S', 'Puerto Viejo (Southern Caribbean)', 'Costa Rica', 'Costa Rica''s Southern Caribbean', 'live', 'verified', 'tropicalBeach', 'Costa Rica', '{"tropical","expedition","culture","wildlife","ocean"}', '{"tropical"}', '{"essential","comfort"}', null, null, '{"key_facts":["Puerto Viejo de Talamanca is Costa Rica''s Southern Caribbean counter-culture coast: Afro-Caribbean + Bribri, reggae-slow beach towns, distinct from the Pacific side.","The Caribbean coast INVERTS the national weather pattern - driest and calmest in Sep-Oct and Feb-Mar, exactly when the Pacific is ''green season'' - a counter-seasonal selling point.","Cahuita National Park protects both a coral reef (guided snorkel only, ~$20pp) and a coastal rainforest walk with sloths, monkeys, iguanas and coatis.","Salsa Brava is an expert-only shallow reef break over sharp coral; beginners surf the Playa Cocles beach break; Punta Uva and Manzanillo are the calm swimming beaches.","Access is international via SJO (San Jose), then a ~4-4.5 hr drive southeast via Limon - a real distance, not a short transfer."],"safety":{"emergency":"911","ambulance_alt":"128 (Red Cross)","hospital":"24-hr private clinic in Puerto Viejo + public clinic Hone Creek (~5km); nearest hospital Limon (~1hr); major trauma routes to San Jose","medical_evacuation":"AirMed/Global Rescue-type air ambulance toward San Jose/repatriation; ~US$50,000 often full straight","l2_disclosure":true,"petty_crime":"opportunistic theft is main risk (phones/wallets/purses); don''t leave beach valuables unattended, avoid poorly lit streets alone at night, don''t resist a robbery","air_access_verified":"SJO (San Jose) -> ~4-4.5 hr drive via Limon to Puerto Viejo (distance flag)","riptide":"Caribbean riptide risk; Salsa Brava = expert-only reef break over sharp coral; swim at calmer beaches (Punta Uva, Manzanillo)","wildlife":"snake/wildlife on jungle & national-park trails - go guided, stay on trail, no-touch","dengue":"seasonal mosquito-borne risk, occasional outbreaks; repellent advised","malaria":"low/localized; negligible in beach-town zone; relevant only for deep-forest hikes","water":"generally potable in Costa Rica incl. most of this zone; sensitive travelers/remote lodges may prefer bottled - confirm at property","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-09-01T16:20:27Z","page_updated":"2026-05-19T11:42:25+01:00","source_country":"costa-rica","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"counter_seasonal_peak_1":"Sep-Oct (Caribbean INVERTS national pattern: driest/calmest, best Cahuita snorkel visibility, rates ~30% lower)","counter_seasonal_peak_2":"Feb-Mar (driest most-reliable beach weather; least rain in March ~175mm)","surf_curve":"Salsa Brava swell Dec-Mar (dry-season window)","green_wet_variance":"wettest in the between-season troughs (~May-Aug bracket + secondary Nov-Dec lift); sell insured/refundable, lead with wildlife+reef-between-fronts","events":"Limon Carnival every October (Limon city; soca/calypso/reggae; Puerto Viejo lodging hub) + local Puerto Viejo/Manzanillo calypso nights (confirm 2026 dates)","fill_the_beds":"wet troughs lead with Jaguar Rescue Center, Sloth Sanctuary, Bribri cacao tour, indoor culture + reef/beach between fronts","campaign_start_trigger":"Sep-Oct counter-seasonal push fires mid-late Aug 2026 (headline); Feb-Mar + Salsa Brava fires late-Dec 2025/early-Jan 2026; Limon-Carnival fires late-Aug/early-Sep 2026","fire_date":"2026-08-17","booking_lead":"Sep-Oct value 3-5 weeks; Feb-Mar dry peak 6-10 weeks; Limon-Carnival Oct lodging 4-8 weeks"},"jewels":[{"name":"Cahuita National Park - reef snorkel + coastal wildlife walk","status":"live","tier":"essential","hook":"Guided coral-reef snorkel PLUS a rainforest walk with sloths, monkeys, iguanas and coatis - reef + rainforest in one park.","bookable_category":"guided snorkel + wildlife hike","source":"https://mytanfeet.com/costa-rica-national-park/cahuita-national-park-costa-rica/","si":"expedition","blurb":"Guided coral-reef snorkel PLUS a rainforest walk with sloths, monkeys, iguanas and coatis - reef + rainforest in one park.","commission":"local-operator direct / affiliate 4-8%; park entry ($5 Puerto Vargas) + guide fee (~$20pp) pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","tropical","wildlife"],"shelf_fit":{"culture":"destination","expedition":"primary","ocean":"destination","tropical":"evidenced","wildlife":"evidenced"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["operator","affiliate","guide"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Punta Uva + Playa Cocles + Punta Cocles beach corridor","status":"live","tier":"essential","hook":"Ivory-sand corridor - Punta Uva the calm swim/snorkel jewel, Cocles the beginner surf beach.","bookable_category":"self-guided beach","source":"https://mytanfeet.com/costa-rica-beach-information/punta-uva-puerto-viejo/","si":"tropical","blurb":"Ivory-sand corridor - Punta Uva the calm swim/snorkel jewel, Cocles the beginner surf beach.","commission":"none direct (drives lodging + F&B + kayak/surf attach)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean","tropical"],"shelf_fit":{"culture":"destination","expedition":"destination","ocean":"evidenced","tropical":"primary","wildlife":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Tropical Islands / Beaches","si_map_basis":"normalised from free text ''Tropical Islands / Beaches'' by gen_normalise_jewel_si"},{"name":"Manzanillo / Gandoca-Manzanillo Wildlife Refuge","status":"future","tier":"comfort","hook":"23,348-acre refuge from Punta Uva to Panama; 500+ ha protected reef, year-round dolphins, turtles, manatees, Manzanillo->Punta Mona coastal trail.","bookable_category":"guided snorkel/dolphin-watch + coastal hike","source":"https://costarica.org/beaches/caribbean/manzanillo/","si":"wildlife","blurb":"23,348-acre refuge from Punta Uva to Panama; 500+ ha protected reef, year-round dolphins, turtles, manatees, Manzanillo->Punta Mona coastal trail.","commission":"local-operator direct / affiliate; refuge entry pass-through","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["tropical","wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","ocean":"destination","tropical":"evidenced","wildlife":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Jaguar Rescue Center","status":"future","tier":"essential","hook":"Rehab center for Caribbean wildlife - monkeys, sloths, kinkajous, toucans, macaws, snakes; guided tours.","bookable_category":"scheduled guided tour","source":"https://mylatinlife.com/puerto-viejo-talamanca-costa-rica-travel-guide/","si":"wildlife","blurb":"Rehab center for Caribbean wildlife - monkeys, sloths, kinkajous, toucans, macaws, snakes; guided tours.","commission":"affiliate / operator direct; admission largely pass-through/donation","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","ocean":"destination","tropical":"destination","wildlife":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Sloth Sanctuary (Cahuita)","status":"future","tier":"comfort","hook":"Sloth rescue + canoe wildlife-viewing tour near Cahuita.","bookable_category":"guided sanctuary + canoe tour","source":"https://mylatinlife.com/puerto-viejo-talamanca-costa-rica-travel-guide/","si":"wildlife","blurb":"Sloth rescue + canoe wildlife-viewing tour near Cahuita.","commission":"affiliate / operator direct; admission pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","ocean":"destination","tropical":"destination","wildlife":"primary"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Bribri indigenous territory + cacao/chocolate tour","status":"future","tier":"comfort","hook":"Living-Indigenous immersion in the Talamanca foothills - walk the cacao agroforest, ferment/roast/grind, medicinal plants, home-cooked meal, waterfall.","bookable_category":"community cultural tour","source":"https://williestourscostarica.com/tours-old/bribri-indigenous-village-chocolate-tour-medicinal-plants/","si":"culture","blurb":"Living-Indigenous immersion in the Talamanca foothills - walk the cacao agroforest, ferment/roast/grind, medicinal plants, home-cooked meal, waterfall.","commission":"community-operator direct / affiliate; community fee pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","ocean":"destination","tropical":"destination","wildlife":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Salsa Brava reef break (watch or expert-only surf)","status":"live","tier":"essential","hook":"One of Central America''s heaviest waves over shallow coral - a spectator draw, an expert-only ride Dec-Mar; beginners to Cocles.","bookable_category":"expert self-guided / beginner-beach coaching","source":"https://www.kimkim.com/e/surf-lessons-at-salsa-brava-in-puerto-viejo-de-talamanca","si":"expedition","blurb":"One of Central America''s heaviest waves over shallow coral - a spectator draw, an expert-only ride Dec-Mar; beginners to Cocles.","commission":"affiliate on beginner surf lessons/rentals; watching free (F&B attach)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","ocean","tropical"],"shelf_fit":{"culture":"destination","expedition":"primary","ocean":"evidenced","tropical":"evidenced","wildlife":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Punta Uva clear-kayak (jungle river + emerald coast)","status":"future","tier":"comfort","hook":"Clear kayaks up the jungle river/coast spotting toucans, monkeys, iguanas, river turtles.","bookable_category":"guided clear-kayak","source":"https://caribesurcr.com/tour-item/clear-kayak-tour/","si":"ocean","blurb":"Clear kayaks up the jungle river/coast spotting toucans, monkeys, iguanas, river turtles.","commission":"affiliate / operator direct","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean","wildlife"],"shelf_fit":{"culture":"destination","expedition":"destination","ocean":"primary","tropical":"destination","wildlife":"evidenced"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Afro-Caribbean cuisine (rondon + rice-and-beans in coconut)","status":"future","tier":"essential","hook":"The coast''s Creole table - rondon coconut-milk stew, rice-and-beans in coconut, calypso-culture kitchens.","bookable_category":"self-guided + food/culture tours","source":"https://soullifetravel.net/bribri-chocolate-indigenous-culture-costa-rica/","si":"culture","blurb":"The coast''s Creole table - rondon coconut-milk stew, rice-and-beans in coconut, calypso-culture kitchens.","commission":"affiliate on food tours; otherwise F&B attach","wells":["activities","eat"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","ocean":"destination","tropical":"destination","wildlife":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Limon Carnival (October) + calypso nights","status":"future","tier":"essential","hook":"The coast''s flagship Afro-Caribbean festival (soca/calypso/reggae/parades) in Limon each October; Puerto Viejo lodging hub.","bookable_category":"self-guided + festival-week lodging","source":"https://www.takeyourbackpack.com/backpacking-in-costa-rica/visit-limon-carnival/","si":"culture","blurb":"The coast''s flagship Afro-Caribbean festival (soca/calypso/reggae/parades) in Limon each October; Puerto Viejo lodging hub.","commission":"lodging AOR + affiliate on festival transfers","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination","ocean":"destination","tropical":"destination","wildlife":"destination"},"commission_lane":["affiliate","event"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"Do you need a guide to snorkel Cahuita National Park?","a":"Yes — Cahuita''s reef snorkel is guided-only (~US$20 pp); you can''t bring your own gear and go solo, single-use plastics are banned, and no-touch coral discipline applies. Book the guided boat snorkel for best visibility Mar–Apr and Aug–Oct.","source":"mytanfeet.com, 2026-07-06","si_tag":"expedition","accessed":"2026-07-06"},{"q":"Is Puerto Viejo good for a honeymoon?","a":"Yes, as barefoot-luxury rather than palace-luxury. The ceiling is premier-to-luxury boutique — Le Cameleon (SLH) from ~US$186/night, or the 7-bungalow Tierra de Sueños wellness hideaway in Playa Chiquita — jungle-beach seclusion, adults-leaning, no marble required.","source":"lecameleonhotel.com, 2026-07-06","si_tag":"romance","accessed":"2026-07-06"},{"q":"When is Limón Carnival, and can you base in Puerto Viejo for it?","a":"Yes. Limón Carnival runs every October (started 1949) in the port city of Limón — soca, calypso, reggae and parades — with Puerto Viejo a common lodging hub a short hop south; confirm exact 2026 dates on live tracking.","source":"takeyourbackpack.com, 2026-07-06","si_tag":"culture","accessed":"2026-07-06"},{"q":"Can you see sloths and dolphins around Puerto Viejo?","a":"Easily. The town is ringed by jungle, so sloths, monkeys and colorful birds show right off the coast road, and the 23,348-acre Gandoca-Manzanillo refuge holds year-round bottlenose and tucuxi dolphins plus four sea-turtle species (Mar–Jul).","source":"costarica.org, 2026-07-06","si_tag":"wildlife","accessed":"2026-07-06"},{"q":"Can beginners surf Salsa Brava?","a":"No. Salsa Brava is an expert-only, powerful, shallow reef break over sharp coral — one of Central America''s heaviest waves — and it injures those who fall. Beginners and intermediates belong at the Playa Cocles beach break or a gentler beach; distinguish clearly at point of sale.","source":"kimkim.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"},{"q":"How far is medical care if something goes wrong?","a":"A 24-hour private clinic in Puerto Viejo handles emergencies, with a public clinic in Hone Creek (~5 km) and the nearest large hospital in Limón (~1 hr); major trauma routes to San José. Air-evac cases can run ~US$50,000, often full straight — carry robust travel + air-evac insurance.","source":"puntauvarealty.com, 2026-07-06 · remax-oceansurf-cr.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"}],"seo":{"meta_title":"Puerto Viejo de Talamanca, Costa Rica Travel Guide 2026 - Southern Caribbean, Sloths, Salsa Brava & Cahuita | TravelWell.World","meta_description":"Plan Costa Rica''s Southern Caribbean: Puerto Viejo de Talamanca, Cahuita reef & wildlife, Punta Uva & Manzanillo beaches, Salsa Brava surf, Bribri chocolate, boutique jungle-beach lodges, clear safety guidance, and the counter-seasonal Sep-Oct sweet spot.","slug":"puerto-viejo-costa-rica","jsonld_type":"TouristDestination","content_freshness":"2026-07-06","search_language":"es-CR","local_keywords":["Puerto Viejo de Talamanca","Cahuita parque nacional","playas Caribe Sur Costa Rica","Punta Uva Costa Rica","refugio Gandoca-Manzanillo","tour de cacao Bribri","surf Salsa Brava","perezosos Puerto Viejo","Carnaval de Limon"],"hreflang":["en","es-CR"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-20T14:54:18Z","source_updated":"2026-05-19T11:42:25+01:00"}]},"primary_keyword":["Puerto Viejo Costa Rica travel guide","Southern Caribbean Costa Rica","Cahuita National Park snorkeling"]},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"expedition","status":"live"},{"si":"culture","status":"future"},{"si":"wildlife","status":"future"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Le Cameleon Boutique Hotel","price_tier":"luxury","virtuoso":false,"slh_member":true,"earning":"on application / host-Virtuoso / SLH trade / Fora","mor_posture":true,"note":"Playa Cocles beachfront; Small Luxury Hotels of the World; 51 rooms + 7 suites + 3 villas; the coast''s ceiling","source":"https://www.lecameleonhotel.com/"},{"name":"Tierra de Suenos Lodge & Wellness Center","price_tier":"premier-luxury","virtuoso":false,"earning":"host-agency AOR / Fora","mor_posture":true,"note":"7 hardwood Caribbean bungalows, Playa Chiquita; wellness/yoga hideaway","source":"https://tierradesuenoslodge.com/"},{"name":"Namuwoki Lodge","price_tier":"premier","virtuoso":false,"earning":"host-agency AOR / Fora","mor_posture":true,"note":"17 bungalows/villas, Playa Chiquita (Bribri ''Home of the Jaguar''); spa + restaurant",