","tier":"comfort","source":"https://thesurfatlas.com/surfing-mexico/punta-mita-surf/ (Accessed 2026-07-07)","hook":"The peninsula''s social beach — beginner surf, beach-club dining, the whale-tour pier","si":"tropical","blurb":"The peninsula''s social beach — beginner surf, beach-club dining, the whale-tour pier","commission":"affiliate dining/activity + resort night","accessed":"2026-07-07","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean","tropical"],"shelf_fit":{"expedition":"destination","ocean":"evidenced","romance":"destination","tropical":"primary"},"commission_lane":["affiliate","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Sayulita / San Pancho day","tier":"comfort","source":"https://www.rivieranayarit.com/activity/water/tour-marietas-island-hidden-beach-punta-mita/ (Accessed 2026-07-07)","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Bohemian surf-and-art villages ~30–45 min north — day-out contrast to Punta Mita polish","si":"tropical","blurb":"Bohemian surf-and-art villages ~30–45 min north — day-out contrast to Punta Mita polish","when":"December–April","commission":"DMC day-tour + affiliate activity","accessed":"2026-07-07","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["ocean","tropical"],"shelf_fit":{"expedition":"destination","ocean":"evidenced","romance":"destination","tropical":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Jack Nicklaus Pacífico — Tail of the Whale","tier":"premier","source":"https://nicklausdesign.com/course/puntamita/ (Accessed 2026-07-07)","hook":"The world''s only natural-island par-3 green, 199 yds offshore, walkable at low tide; 7,104-yd par-72 with eight ocean holes","si":"expedition","blurb":"The world''s only natural-island par-3 green, 199 yds offshore, walkable at low tide; 7,104-yd par-72 with eight ocean holes","commission":"golf package via resort/DMC + Virtuoso resort night","accessed":"2026-07-07","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition","tropical"],"shelf_fit":{"expedition":"primary","ocean":"destination","romance":"destination","tropical":"evidenced"},"commission_lane":["DMC","package","consortia","hotel"],"commission_embedded":false,"commission_basis":"2026-10-05: Fora removed - excluded by David 2026-09-05; the remaining route kept","commission_was":"golf package via resort/DMC + Fora/Virtuoso resort night"},{"name":"Bahía course (Nicklaus 2009)","tier":"premier","source":"https://nicklausdesign.com/course/puntamita2/ (Accessed 2026-07-07)","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"360° Banderas Bay views, a beach hole by the El Faro surf spot; the more technical of the two","si":"expedition","blurb":"360° Banderas Bay views, a beach hole by the El Faro surf spot; the more technical of the two","when":"December–April","commission":"golf package + resort","accessed":"2026-07-07","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","ocean","tropical"],"shelf_fit":{"expedition":"primary","ocean":"evidenced","romance":"destination","tropical":"evidenced"},"commission_lane":["package","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Islas Marietas — Playa del Amor","tier":"comfort","source":"https://en.wikipedia.org/wiki/Islas_Marietas_National_Park (Accessed 2026-07-07)","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"SEMARNAT-permitted crater beach reached by swimming a cave tunnel; ~116 visitors/day, Wed–Sun, ~15-min boat","si":"expedition","blurb":"SEMARNAT-permitted crater beach reached by swimming a cave tunnel; ~116 visitors/day, Wed–Sun, ~15-min boat","when":"December–April","commission":"SEMARNAT-permitted operator (non-commissionable park fee) + resort night","accessed":"2026-07-07","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition","ocean","tropical"],"shelf_fit":{"expedition":"primary","ocean":"evidenced","romance":"destination","tropical":"evidenced"},"commission_lane":["operator","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Humpback whale-watching, Banderas Bay","tier":"premier","source":"https://villaexperience.com/whale-watching-punta-mita-guide-2026/ (Accessed 2026-07-07)","hook":"300–500 humpbacks each Dec–Mar; El Anclote pier to sighting zones in 15–30 min","si":"expedition","blurb":"300–500 humpbacks each Dec–Mar; El Anclote pier to sighting zones in 15–30 min","commission":"licensed operator + Virtuoso resort","accessed":"2026-07-07","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","ocean":"destination","romance":"destination","tropical":"destination"},"commission_lane":["operator","consortia","hotel"],"commission_embedded":false,"commission_basis":"2026-10-05: Fora removed - excluded by David 2026-09-05; the remaining route kept","commission_was":"licensed operator + Fora/Virtuoso resort"},{"name":"El Anclote / La Lancha surf","tier":"comfort","source":"https://wildmex.com/activities/surfing-punta-mita-surf-lessons/ (Accessed 2026-07-07)","hook":"Beginner cove + the region''s best peeling waves; guided lessons $60–180 depending on group/private","si":"expedition","blurb":"Beginner cove + the region''s best peeling waves; guided lessons $60–180 depending on group/private","commission":"surf school (affiliate/DMC) + resort","accessed":"2026-07-07","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","ocean"],"shelf_fit":{"expedition":"primary","ocean":"evidenced","romance":"destination","tropical":"destination"},"commission_lane":["DMC","affiliate","hotel","school"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for?","a":"Rip currents and dengue, not crime. The Pacific beaches have rip currents and shore break — swim guarded resort beaches and obey the flags — and Nayarit is a high-prevalence dengue state with a May–November transmission peak, so pack repellent for summer stays. Nearest full trauma is Puerto Vallarta (~40 min), then US air-evac.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"Is Punta Mita good for a destination wedding?","a":"It is one of Mexico''s ultra-wedding flagships. Susurros del Corazón (Auberge) alone hosts events for 30–300 guests ~45 minutes from PVR, with reception rental from $2,000, alongside Four Seasons and St. Regis event teams. Villa and resort weddings book 9–12 months out — peak-season cohorts 12+ months.","source":"aubergeresorts.com, 2026-07-07","si_tag":"romance","accessed":"2026-07-07"},{"q":"What''s the best beach and surf for beginners?","a":"El Anclote. It''s a sheltered, sandy-bottom cove with gentle rolling waves — the peninsula''s beginner classroom — while La Lancha, a ~10-minute jungle-trail walk away, holds the most reliable quality waves for confident beginners through intermediates. Guided lessons ($60–180) stage away from the rocks.","source":"thesurfatlas.com / wildmex.com, 2026-07-07","si_tag":"tropical","accessed":"2026-07-07"},{"q":"Is the golf as good as they say?","a":"Yes — it''s a two-course Nicklaus complex with a genuine one-of-a-kind hole. The Pacífico course (7,104-yd par-72, eight ocean holes) has the \"Tail of the Whale,\" the world''s only natural-island green, 199 yards offshore and walkable at low tide; the 2009 Bahía course is the more technical of the two.","source":"nicklausdesign.com, 2026-07-07","si_tag":"expedition","accessed":"2026-07-07"},{"q":"How do I actually visit the Islas Marietas Hidden Beach?","a":"Only with a SEMARNAT-permitted operator, and book weeks ahead. Playa del Amor is capped at ~116 visitors/day, Wed–Sun, reached by a ~15-minute boat then a life-jacketed swim through a low cave tunnel; non-swimmers can''t access it. Never promise a landing without a confirmed permitted slot.","source":"en.wikipedia.org, 2026-07-07","si_tag":"ocean-adventures-—-future","accessed":"2026-07-07"}],"seo":{"meta_title":"Punta Mita, Mexico — Ultra-Luxury Resorts, Private Villas & Whale Season | TravelWell","search_language":"es-MX","local_keywords":["Punta Mita resorts","villas Punta Mita","Four Seasons Punta Mita","bodas Punta Mita","avistamiento de ballenas Riviera Nayarit","Islas Marietas Playa del Amor","golf Punta Mita"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]},"content_freshness":"2026-07-07"},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":null,"ultra":[{"property":"Four Seasons Resort Punta Mita","rooms":"~173 incl. 30 suites + private villas","path":"Fora/Virtuoso","value_add":"FS Preferred credit / upgrade / breakfast","tier":"ultra"},{"property":"The St. Regis Punta Mita","rooms":"89 rooms + 31 suites, butler service","path":"Fora/Virtuoso","value_add":"Marriott Luminous/STARS","tier":"ultra"},{"property":"Susurros del Corazón (Auberge)","rooms":"89 keys (59 rooms/suites + 30 villas)","path":"Fora/Virtuoso + wedding DMC","value_add":"Auberge preferred","tier":"ultra"},{"property":"Conrad Punta de Mita","rooms":"Hilton ultra-resort","path":"Fora/Virtuoso","value_add":"Hilton Impresario","tier":"ultra"},{"property":"Branded private villas (FS / St. Regis / Auberge residences)","rooms":"3–6BR oceanfront estates w/ pools","path":"Fora/Virtuoso or specialist MoR","value_add":"villa-week commission + resort value-add","tier":"ultra"}],"source_verified":null,"hero":{"query":"Punta Mita, Mexico, Mexico"},"geo":{"lat":20.77,"lng":-105.52},"orbit":[{"id":"sayulita-mexico","jewels":10,"si":["tropical","expedition","romance","ocean","culture","family","wildlife"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","coba-mexico","costalegre-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sian-kaan-mexico","teotihuacan-mexico","tlaquepaque-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 92),
