  ('rio-lagartos-mexico', '10S', 'Río Lagartos', 'Mexico', 'Spring breeding grounds of the flamingos', 'live', 'verified', 'oceanAerial', 'Yucatán (Mérida & Chichén Itzá)', '{"expedition","tropical"}', '{"tropical"}', '{"essential","ultra"}', null, null, '{"key_facts":["Ría Lagartos Biosphere Reserve — Yucatán''s flamingo capital; ~35 km boat safari, 400+ bird species","Flamingos breed Apr-Jul, counts near 40,000 — opposite of Celestún''s Nov-Mar peak","Las Coloradas pink lagoons colored by halophilic bacteria/algae; Mexico''s #2 salt operation; no-swim default, drones banned","Remote coast — nearest full trauma care Mérida ~2-2.5 hr; Tizimín ~1 hr, Valladolid ~1.5 hr","Cash economy (one ATM, runs dry); certified federal guides; sunscreen banned on-boat"],"safety":{"emergency_number":"911","air_access_verified":true,"nearest_trauma":"Mérida private hospitals (~2-2.5 hr); Valladolid hospital (~1.5 hr) w/ 24-hr ambulance transfer; Tizimín (~1 hr) basic","remote_flag":true,"activity_fires":["boat-safari life vests + CONANP-licensed operator","sun/dehydration open water","no-touch/no-flush wildlife","Las Coloradas no-swim salt lagoon","remote medevac distance","mangrove/mosquito"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"inflection_curve_start":"2026-03-15","peak":"Apr-Jul (flamingo breeding, ~40,000 birds)","fire_date":"2026-03-01","shoulder":"Aug-Oct (green/rainy)","booking_lead_weeks":"4-8","notes":"Río Lagartos flamingos peak Apr-Sep (breeding) — OPPOSITE window to Celestún (Nov-Mar). Follow-the-sun within Yucatán. Las Coloradas pinkest Mar + Jul-Aug. Sharpen on live tracking."},"jewels":[{"name":"Flamingo boat safari (Ría Lagartos)","tier":"essential","source":"https://www.getyourguide.com/rio-lagartos-l146496/ttd/","si":"expedition","commission":"DMC (Amstar) / GetYourGuide-Viator affiliate","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","tropical":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Las Coloradas pink lakes (no swim)","tier":"essential","source":"https://travelbooksfood.com/las-coloradas-pink-lakes-of-mexico-yucatan","timing":"Apr-Jul","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Apr-Jul","commission":"activity affiliate + non-commissionable entry pass-through","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''activity affiliate + non-commissionable ''","si_all":["expedition"],"shelf_fit":{"expedition":"primary","tropical":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Crocodile night tour","tier":"essential","source":"https://www.tripadvisor.com/Attraction_Review-g1168987-d1965637-Reviews-Rio_Lagartos_Adventures-Rio_Lagartos_Yucatan_Peninsula.html","timing":"Apr-Jul","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Apr-Jul","commission":"DMC / cooperative referral","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","tropical":"destination"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Mayan mud bath (Baño Maya)","tier":"essential","source":"https://www.tripadvisor.com/Attraction_Review-g1168987-d1965637-Reviews-Rio_Lagartos_Adventures-Rio_Lagartos_Yucatan_Peninsula.html","timing":"Apr-Jul","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Apr-Jul","commission":"bundled in boat tour","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — commission lane ''bundled in boat tour''","si_all":["expedition"],"shelf_fit":{"expedition":"primary","tropical":"destination"},"commission_lane":["bundle"],"commission_embedded":false,"commission_basis":"lane"},{"name":"San Felipe fishing village","tier":"essential","source":"https://www.letstraveltomexico.com/rio-lagartos-yucatan/","timing":"Apr-Jul","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Apr-Jul","commission":"content halo → dining/lodging affiliate","wells":["activities","stay"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["tropical"],"shelf_fit":{"expedition":"destination","tropical":"primary"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"El Cuyo kite / quiet beach","tier":"essential","source":"https://www.letstraveltomexico.com/el-cuyo-yucatan/","timing":"Apr-Jul","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Apr-Jul","commission":"kite-school + guesthouse affiliate/bedbank","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["tropical"],"shelf_fit":{"expedition":"destination","tropical":"primary"},"commission_lane":["affiliate","school"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"When is the best time to see flamingos at Río Lagartos?","a":"April through July, the breeding concentration, when counts reach near 40,000 birds — the exact opposite window from Celestún, which peaks November–March. Counts swing year to year with water level and salinity, so book the reserve and the season, not a promised number, and sharpen on live tracking before committing to a date.","source":"letstraveltomexico.com, 2026-07-06","si_tag":"expedition","accessed":"2026-07-06"},{"q":"Can you swim in the Las Coloradas pink lakes?","a":"Default no — plan for it. Las Coloradas is a working industrial hypersaline salt operation (Mexico''s #2), not a swim beach; entry is rule-bound and guide-mandatory, and drones are banned by the salt company. A 2026 report suggests a limited, pre-booked 10-minute swim window may again be permitted at specific spots, but treat that as unconfirmed and volatile and default to the no-swim expectation.","source":"travelbooksfood.com, 2026-07-06","si_tag":"expedition","accessed":"2026-07-06"},{"q":"What else will I see besides flamingos?","a":"A full biosphere: 400+ logged bird species, crocodiles on the after-dark night run (mellow and family-friendly for older kids), the white halophilic-clay \"Baño Maya\" mud bath, and the salt-flat geology behind the pink. The reserve is a dedicated birding vertical once the Wildlife SI opens.","source":"tripadvisor.com, 2026-07-06","si_tag":"wildlife","accessed":"2026-07-06"},{"q":"Is there a beach at Río Lagartos?","a":"Yes — three quiet ones. Cancunito is a white-sand swim beach near town, San Felipe (12 km west) is a pastel fishing village with fresh seafood, and El Cuyo (45 min east) is a resort-free barrier-beach village inside the biosphere with steady side-shore wind for kitesurfing, peaking Dec–Feb.","source":"letstraveltomexico.com, 2026-07-06","si_tag":"tropical","accessed":"2026-07-06"},{"q":"What''s the real risk to plan for in Río Lagartos?","a":"Distance to trauma care, not crime. The town has only a basic clinic; Tizimín is ~1 hr, Valladolid''s hospital ~1.5 hr (with 24-hr ambulance transfer for serious cases), and Mérida''s full private hospitals ~2–2.5 hr. Serious injury means a long road transfer, so build the medevac distance into expectations, especially for older travelers, and carry insurance.","source":"yucatanmagazine.com, 2026-07-06","si_tag":"safety","accessed":"2026-07-06"}],"seo":{"meta_title":"Río Lagartos & Las Coloradas: Flamingos and Pink Lakes | TravelWell.World","search_language":"en","local_keywords":["flamencos Río Lagartos","Las Coloradas Yucatán","reserva de la biosfera Ría Lagartos","tour flamencos Yucatán","baño Maya Río Lagartos","El Cuyo kitesurf"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-06","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"Co