co","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-mexico","punta-mita-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sayulita-mexico","sian-kaan-mexico","teotihuacan-mexico","tlaquepaque-mexico","todos-santos-mexico","tulum-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 95),
  ('roatan-honduras', '10S', 'Roatán, Honduras (Bay Islands)', 'Honduras', 'Roatán', 'live', 'verified', 'oceanAerial', 'Honduras', '{"diveglobal","expedition","tropical"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Roatán sits on the Mesoamerican Barrier Reef, the second-largest coral-reef system on earth; Bay Islands ranked highest in coral health in the 2015 Mesoamerican assessment.","30+ dive shops on the west side; ~30 named dive sites within a 10-minute boat ride off West Bay/West End, with walls dropping past 100 ft and the El Aguila/Odyssey wrecks.","The Roatán Aggressor IV liveaboard runs Sat->Sat (18 guests, ~24-27 dives) across Roatán, Cayos Cochinos, and Utila.","Whale sharks are snorkel-only and protected; Utila (a short hop from Roatán) offers year-round potential peaking late March-April.","Roatán has an on-island recompression chamber (Cornerstone Hyperbaric, adjacent to Anthony''s Key Resort; DAN IPPN partner) — a first-response advantage for wall diving."],"safety":{"emergency":"911","hyperbaric_chamber":"Cornerstone Hyperbaric Chamber & Clinic, Sandy Bay (adjacent to Anthony''s Key Resort) — on-island recompression chamber + ER/lab/pharmacy, DAN International Preferred Provider Network partner","air_access_verified":"Direct air into Juan Manuel Gálvez Intl (RTB), Roatán — Bay Islands reachable without transiting mainland gang zones","no_fly_after_diving":"18-24 hours before RTB departure flight (DAN protocol)","environmental":["west-wall depth discipline","currents on walls/channels","dengue (CDC)","bottled water only"],"fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/honduras","read":"2026-09-01T16:19:22Z","page_updated":"2026-07-29T16:40:19+01:00","source_country":"honduras","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"best_visibility":"July-September","curve_st